        "id": "key-methodology-in-30-seconds",
        "heading": "Key Methodology in 30 Seconds",
        "blocks": [
          {
            "type": "bullets",
            "items": [
              {
                "lead": "Evidence Grades (A–E):",
                "text": "every factual claim carries one:"
              }
            ]
          },
          {
            "type": "text",
            "body": "- **Grade A (Primary Empirical):** Official specifications, canonical source code, RFCs, or primary documentation with explicit URL anchor. - **Grade B (Secondary Empirical):** Peer-reviewed papers, reproducible third-party benchmarks, published postmortems, or corroborated engineering reports. - **Grade C (Vendor & Practitioner):** Vendor marketing, product whitepapers, vendor benchmarks, conference talks, or interested-party documentation. - **Grade D (Informal & Opinion):** Blog posts, forum discussions, StackOverflow answers, or model memory recall (capped at Grade D). - **Grade E (Speculative & Unsubstantiated):** Unverified hypotheses, uncorroborated parametric recall, or ungrounded assertions."
          },
          {
            "type": "bullets",
            "items": [
              {
                "lead": "Two-Way vs. One-Way Doors:",
                "text": "Two-Way doors (reversal cost low) need ~70% confidence and run fast. One-Way doors (persistence schemas, data migrations, public API contracts) require corroborated Grade A/B evidence, falsification checks, and locked reversal triggers."
              },
              {
                "lead": "Structured Falsification:",
                "text": "Prompts explicitly direct the AI to hunt for failure modes and disconfirming evidence against the leading candidate, preventing confirmation bias."
              }
            ]
          }
        ]
